function load(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');return {...structuredClone(stateDefault),...raw,annualPlan:{...stateDefault.annualPlan,...(raw.annualPlan||{})},monthlyPlans:Array.isArray(raw.monthlyPlans)?raw.monthlyPlans:[]}}catch(e){return structuredClone(stateDefault)}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));renderAll()}catch(e){alert('Мәтіндік деректерді сақтау мүмкін болмады. Ескі үлкен PDF-терді резервтік көшірмеге сақтап, кейін алып тастаңыз. '+e.message);throw e}}
function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function avg(a){const nums=a.map(Number).filter(n=>Number.isFinite(n));return nums.length?nums.reduce((x,y)=>x+y,0)/nums.length:0}
function pct(n,d){return d?Math.round((n/d*100)*10)/10:0}
function dateKk(){return new Intl.DateTimeFormat('kk-KZ',{dateStyle:'full'}).format(new Date())}

document.getElementById('todayText').textContent=dateKk();
document.getElementById('menuBtn').onclick=()=>document.getElementById('sidebar').classList.toggle('open');
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function showPage(p){currentPage=p;document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p).classList.add('active');document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===p));document.getElementById('pageTitle').textContent=document.querySelector(`.nav-item[data-page="${p}"] span`).textContent;document.getElementById('sidebar').classList.remove('open'); if(p==='dashboard')setTimeout(drawCharts,30)}

const schoolForm=document.getElementById('schoolForm');
schoolForm.onsubmit=e=>{e.preventDefault();state.school=Object.fromEntries(new FormData(schoolForm));save();toast('Мектеп ақпараты сақталды')};
function fillSchool(){Object.entries(state.school).forEach(([k,v])=>{if(schoolForm.elements[k])schoolForm.elements[k].value=v||''});document.getElementById('schoolHero').textContent=state.school.schoolName||'Мектеп атауын енгізіңіз';document.getElementById('yearBadge').textContent=state.school.schoolYear||'Оқу жылы';const sum=document.getElementById('schoolSummary');if(sum){const f=state.school||{};const counts=[['Педагог-шебер',f.masterCount],['Педагог-зерттеуші',f.researcherCount],['Педагог-сарапшы',f.expertCount],['Педагог-модератор',f.moderatorCount]];sum.innerHTML='<h4>Мектептің қысқаша мәліметтері</h4><div class="school-summary-grid">'+[['Сыныптар саны',f.classCount],...counts].map(([name,v])=>'<div class="school-summary-stat"><span>'+esc(name)+'</span><strong>'+esc(v===''||v==null?'—':v)+'</strong></div>').join('')+'</div>'+(f.address?'<p class="school-address">📍 '+esc(f.address)+'</p>':'')}}

function badge(v){let c='blue';if(/Орындалды|Жоғары|Жеткілікті/.test(v))c='green';else if(/өтті|Орындалмады|Назар/.test(v))c='red';else if(/Орташа|Орындалуда/.test(v))c='orange';return `<span class="badge ${c}">${esc(v)}</span>`}
function options(arr,val=''){return `<option value="">Таңдаңыз</option>`+arr.map(x=>`<option ${String(x)===String(val)?'selected':''}>${esc(x)}</option>`).join('')}
function field(f,val=''){const req=f.required?'required':'';if(f.type==='select')return `<label>${f.label}<select name="${f.name}" ${req}>${options(f.options||[],val)}</select></label>`;if(f.type==='textarea')return `<label class="${f.full?'full':''}">${f.label}<textarea name="${f.name}" rows="3" ${req}>${esc(val)}</textarea></label>`;return `<label class="${f.full?'full':''}">${f.label}<input type="${f.type||'text'}" name="${f.name}" value="${esc(val)}" ${req}></label>`}
