 const tabs=[['orders','📜 Бұйрықтар'],['zero','📊 «0» білім кесіндісі'],['bzb','📝 БЖБ-ТЖБ талдауы'],['standards','📚 Пәндер бойынша білім беру стандартының орындалуы'],['international','🌍 Халықаралық зерттеу']];
