window.openQualityRecord=(type,rowid=null)=>{const cfg=type==='qualityBzb'?qualityBzbConfigs.qualityBzb:type==='qualityBzbConclusion'?qualityBzbConfigs.qualityBzbConclusion:type==='qualityStandards'?qualityStandardConfig:type==='qualityInternational'?qualityInternationalConfig:{title:'«0» білім кесіндісі',fields:[{name:'subject',label:'Пән',type:'select',options:subjects,required:true},{name:'teacher',label:'Пән мұғалімі',required:true},{name:'five',label:'5',type:'number'},{name:'four',label:'4',type:'number'},{name:'three',label:'3',type:'number'},{name:'two',label:'2',type:'number'},{name:'quality',label:'Білім сапасы',type:'number'},{name:'achievement',label:'Үлгерімі',type:'number'}]};const row=rowid?(state[type]||[]).find(x=>x.id===rowid):{};document.getElementById('modalTitle').textContent=rowid?`${cfg.title}: өңдеу`:`${cfg.title}: жаңа жазба`;mf.innerHTML=cfg.fields.map(f=>field(f,row?.[f.name]||'')).join('')+`<div class="full"><button class="btn primary" type="submit">Сақтау</button></div>`;mf.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(mf));['five','four','three','two','quality','achievement','high','medium','low'].forEach(k=>{if(k in data)data[k]=data[k]===''?'':Number(data[k])});if(rowid)state[type]=state[type].map(x=>x.id===rowid?{...x,...data}:x);else state[type].push({id:id(),...data});mb.classList.remove('show');save();toast('Жазба сақталды')};mb.classList.add('show')};
