      <div class="month-grid">${months.map((x,i)=>`<div class="month-card ${x.dataUrl?'has-file':''}"><div class="month-head"><h4>${x.month}</h4>${x.dataUrl?'<span class="badge green">PDF енгізілді</span>':'<span class="badge blue">Бос</span>'}</div><p class="muted">${x.dataUrl?esc(x.fileName||'Жоспар.pdf'):'Жоспар енгізілмеген'}</p><div class="month-actions">${x.dataUrl?`<button class="btn small primary" onclick="viewMonthlyPlan('${esc(x.month)}')">Көру</button><button class="btn small ghost" onclick="openMonthlyPlanModal('${esc(x.month)}')">Ауыстыру</button><button class="btn small danger" onclick="deleteMonthlyPlan('${esc(x.month)}')">Жою</button>`:`<button class="btn small primary" onclick="openMonthlyPlanModal('${esc(x.month)}')">+ PDF енгізу</button>`}</div></div>`).join('')}</div>
