  el.querySelectorAll('.plan-tab').forEach(b=>b.onclick=()=>{el.querySelectorAll('.plan-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');el.querySelectorAll('.plan-tab-content').forEach(x=>x.style.display='none');document.getElementById(b.dataset.tab==='annual'?'annualPlanTab':'monthlyPlanTab').style.display='block'});
  refreshAnnualPreview();const input=document.getElementById('annualPdfInput'); if(input) input.onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.type!=='application/pdf'){alert('Тек PDF файлын енгізіңіз.');return}const dataUrl=await fileToDataURL(f);state.annualPlan={name:'Жылдық жоспар',dataUrl,fileName:f.name,uploadedAt:new Date().toLocaleString('kk-KZ')};save();toast('Жылдық жоспар PDF ретінде сақталды')};
