let upbringingTab=0;
function upbringingRows(i=upbringingTab){if(!state.upbringingSections||typeof state.upbringingSections!=='object')state.upbringingSections={};return state.upbringingSections[upbringingGroups[i].storeKey]||[]}
function upbringingCount(){return Object.entries(state.upbringingSections||{}).filter(([k])=>k.startsWith('v9_')).reduce((n,[k,a])=>n+(Array.isArray(a)?a.length:0),0)}
function renderUpbringing(){
 const g=upbringingGroups[upbringingTab],rows=upbringingRows(),root=document.getElementById('tasks');
 if(!root)return;
 const fields=g.fields.filter(f=>!['pdf','file'].includes(f[2])).slice(0,4);
 const groups=[...new Set(upbringingGroups.map(x=>x.group))];
 const currentGroup=g.group;
 root.innerHTML=`<div class="card"><div class="card-head"><div><h3>Тәрбие процесінің, өткізілген іс-шаралардың сапасын бақылау</h3><p>13 негізгі бағыт · PDF құжаттар және анықтамалар</p></div><span class="badge blue">${upbringingCount()} жазба</span></div>
 <div class="up-layout"><nav class="up-nav" aria-label="Тәрбие жұмысының бөлімдері">${groups.map((group,idx)=>`<div class="up-group ${currentGroup===group?'is-active':''}"><button type="button" class="up-group-btn" onclick="selectUpbringingGroup(${idx})"><span>${esc(group)}</span><span class="up-count">${upbringingGroups.filter(x=>x.group===group).reduce((n,x)=>n+((state.upbringingSections||{})[x.storeKey]||[]).length,0)}</span></button>${currentGroup===group?`<div class="up-subnav">${upbringingGroups.map((x,i)=>x.group===group?`<button type="button" class="btn small ${i===upbringingTab?'primary':'ghost'}" onclick="selectUpbringingTab(${i})">${esc(x.title)}</button>`:'').join('')}</div>`:''}</div>`).join('')}</nav>
 <div class="up-main"><div class="card-head"><div><h3>${esc(g.title)}</h3><p>${esc(g.group)} · Жазба саны: ${rows.length}</p></div><button class="btn primary" onclick="openUpbringingRecord()">+ ${g.fields.every(f=>f[2]==='pdf')?'PDF жүктеу':'Жазба қосу'}</button></div>
 <div class="toolbar"><input class="search" aria-label="Жазбаларды іздеу" placeholder="Жазбаларды іздеу..." oninput="filterTable('upbringing',this.value)"></div>
 <div class="table-wrap"><table id="table-upbringing"><thead><tr>${fields.map(f=>`<th>${esc(f[1])}</th>`).join('')}<th>Тіркемелер</th><th>Әрекет</th></tr></thead><tbody>
 ${rows.length?rows.map(r=>`<tr data-search="${esc(Object.values(r).filter(x=>typeof x==='string'&&!x.startsWith('data:')).join(' ').toLowerCase())}">${fields.map(f=>`<td>${esc(String(r[f[0]]||'').slice(0,120))}</td>`).join('')}<td>${g.fields.filter(f=>['pdf','file'].includes(f[2])).map(f=>r[f[0]+'Data']?`<button class="btn small ghost" onclick="viewUpbringingFile('${r.id}','${f[0]}')">📎 ${esc(r[f[0]+'Name']||f[1])}</button>`:'').join(' ')||'—'}</td><td><button class="btn small ghost" onclick="openUpbringingRecord('${r.id}')">Өңдеу</button> <button class="btn small danger" onclick="deleteUpbringingRecord('${r.id}')">Жою</button></td></tr>`).join(''):`<tr><td class="empty" colspan="${fields.length+2}">Әзірге жазба жоқ. «Жазба қосу» батырмасын басыңыз.</td></tr>`}
 </tbody></table></div></div></div></div>`;
}
window.selectUpbringingGroup=idx=>{const group=[...new Set(upbringingGroups.map(x=>x.group))][idx];const i=upbringingGroups.findIndex(x=>x.group===group);if(i>=0){upbringingTab=i;renderUpbringing()}};

window.selectUpbringingTab=i=>{upbringingTab=i;renderUpbringing()};
window.deleteUpbringingRecord=rid=>{if(confirm('Жазбаны жою керек пе?')){state.upbringingSections[upbringingGroups[upbringingTab].storeKey]=upbringingRows().filter(r=>r.id!==rid);save();toast('Жазба жойылды')}};
window.viewUpbringingFile=(rid,key)=>{const r=upbringingRows().find(x=>x.id===rid);if(r&&r[key+'Data'])openFile(r[key+'Data'])};
window.openUpbringingRecord=rid=>{
 const tab=upbringingTab,g=upbringingGroups[tab],row=upbringingRows(tab).find(r=>r.id===rid)||{};
 document.getElementById('modalTitle').textContent=(rid?'Өңдеу: ':'Жаңа жазба: ')+g.group+' — '+g.title;
 mf.innerHTML=g.fields.map(([key,label,type,opts])=>{
  if(type==='pdf'||type==='file')return `<label class="full">${esc(label)}<input type="file" name="${key}" accept="${type==='pdf'?'.pdf,application/pdf':'.pdf,.jpg,.jpeg,application/pdf,image/jpeg'}" ${row[key+'Data']?'':'required'}></label>${row[key+'Data']?`<p class="full muted">Қазіргі файл: ${esc(row[key+'Name']||'Тіркеме')} (ауыстыру міндетті емес)</p>`:''}`;
  return field({name:key,label,type:type||'text',options:opts,full:type==='textarea',required:true},row[key]||'');
 }).join('')+'<div class="full"><button class="btn primary" type="submit">Сақтау</button></div>';
 mf.onsubmit=async e=>{
  e.preventDefault();const submit=mf.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Сақталуда…';
  const fd=new FormData(mf),data={...row};
  try{
   for(const [key,label,type] of g.fields){
    if(type==='pdf'||type==='file'){
     const f=fd.get(key);
     if(f&&f.size){const ext=f.name.toLowerCase();if(!ext.endsWith('.pdf')&&!(type==='file'&&(ext.endsWith('.jpg')||ext.endsWith('.jpeg'))))throw Error('Тіркеме пішімі жарамсыз: '+label);
      data[key+'Data']=await fileToDataURL(f);data[key+'Name']=f.name;
     }else if(!row[key+'Data'])throw Error('Файлды таңдаңыз: '+label);
    }else data[key]=String(fd.get(key)||'');
   }
   if(!rid)data.id=id();const old=upbringingRows(tab);state.upbringingSections[g.storeKey]=rid?old.map(r=>r.id===rid?data:r):[...old,data];
   try{localStorage.setItem(KEY,JSON.stringify(state))}catch(err){state.upbringingSections[g.storeKey]=old;throw Error('Браузер сақтау орны жеткіліксіз: '+err.message)}
   mb.classList.remove('show');renderAll();toast('Жазба сақталды');
  }catch(err){alert('Сақтау мүмкін болмады: '+err.message)}finally{submit.disabled=false;submit.textContent='Сақтау'}
 };
 mb.classList.add('show');
};

state.normDocuments=(state.normDocuments||[]).map(r=>r.document==='ЕБҚ мен құжат'?{...r,document:'ЕБҚ мен ҮО құжаты'}:r);
const normTypes=['КТЖ','ЕБҚ мен ҮО құжаты','Электронды журнал'];
function normPercent(r){const total=Number(r.total)||0;return total>0?((Number(r.present)||0)/total*100):null}
function renderNormDocuments(){
 const el=document.getElementById('normControl');if(!el)return;
 el.innerHTML=`<div class="card"><div class="card-head"><div><h3>Нормативтік құжаттардың орындалуын және мектеп құжаттамасының жүргізілуін бақылау</h3><p>Бақылау жазбалары және құжаттардың жүргізілуі</p></div></div><div class="tabs"><button class="btn" id="normOldTab">Бақылау жазбалары</button> <button class="btn" id="normDocsTab">Нормативтік құжаттардың жүргізілуі</button></div></div><div id="normContent"></div>`;
 function select(t){
   window.normActiveTab=t;
   document.getElementById('normOldTab').className='btn '+(t==='old'?'primary':'ghost');
   document.getElementById('normDocsTab').className='btn '+(t==='docs'?'primary':'ghost');
   if(t==='old'){
     const c=document.getElementById('normContent');
     const cfg=configs.normControl, rows=state.normControl.map(r=>computed('normControl',r));
     c.innerHTML=`<div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Бақылау жазбалары</h3><p>${cfg.desc}</p></div><button class="btn primary" onclick="openModal('normControl')">+ Жазба қосу</button></div><div class="toolbar"><input class="search" placeholder="Іздеу..." oninput="filterTable('normControl',this.value)"><span class="muted">Барлығы: ${rows.length}</span></div><div class="table-wrap"><table id="table-normControl"><thead><tr>${cfg.cols.map(x=>`<th>${esc(x[1])}</th>`).join('')}<th>Әрекет</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr data-search="${esc(Object.values(r).join(' ').toLowerCase())}">${cfg.cols.map(([k])=>`<td>${esc(r[k]??'')}</td>`).join('')}<td><button class="btn small ghost" onclick="openModal('normControl','${r.id}')">Өңдеу</button> <button class="btn small danger" onclick="removeRow('normControl','${r.id}')">Жою</button></td></tr>`).join(''):`<tr><td colspan="${cfg.cols.length+1}" class="empty">Әзірге дерек жоқ</td></tr>`}</tbody></table></div></div>`;
   }else renderNormDocTable();
 }
 document.getElementById('normOldTab').onclick=()=>select('old');
 document.getElementById('normDocsTab').onclick=()=>select('docs');
 select(window.normActiveTab||'old');
}
function renderNormDocTable(){window.normActiveTab='docs';const el=document.getElementById('normContent');const rows=state.normDocuments||[];
 el.innerHTML=`<div class="card" style="margin-top:16px"><div class="card-head"><div><h3>Нормативтік құжаттардың жүргізілуі</h3><p>Пайыз автоматты түрде: Бар / Жалпы мұғалім саны × 100%</p></div><button class="btn primary" onclick="openNormDoc()">+ Жазба қосу</button></div><div class="toolbar"><input class="search" placeholder="Іздеу..." oninput="filterTable('normDocuments',this.value)"><span class="muted">Барлығы: ${rows.length}</span></div><div class="table-wrap"><table id="table-normDocuments"><thead><tr><th>Құжат</th><th>Жалпы мұғалім саны</th><th>Бар</th><th>Жоқ</th><th>Пайыз</th><th>Ескерту</th><th>Әрекет</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr data-search="${esc([r.document,r.note].join(' ').toLowerCase())}"><td>${esc(r.document)}</td><td>${r.total}</td><td>${r.present}</td><td>${r.absent}</td><td>${normPercent(r)===null?'—':normPercent(r).toFixed(1)+'%'}</td><td>${esc(r.note||'')}</td><td><button class="btn small ghost" onclick="openNormDoc('${r.id}')">Өңдеу</button> <button class="btn small danger" onclick="deleteNormDoc('${r.id}')">Жою</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Әзірге дерек жоқ</td></tr>'}</tbody></table></div></div>`;
}
window.openNormDoc=(rid=null)=>{const r=rid?(state.normDocuments||[]).find(x=>x.id===rid):null;document.getElementById('modalTitle').textContent=rid?'Құжатты өңдеу':'Нормативтік құжат: жаңа жазба';mf.innerHTML=`<label>Құжат<select name="document" required>${normTypes.map(x=>`<option ${r?.document===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Жалпы мұғалім саны<input type="number" name="total" min="1" step="1" required value="${r?.total??''}"></label><label>Бар<input type="number" name="present" min="0" step="1" required value="${r?.present??''}"></label><label>Жоқ<input type="number" name="absent" min="0" step="1" required value="${r?.absent??''}"></label><label class="full">Пайыз (автоматты)<input id="normPreview" readonly placeholder="Бар / Жалпы саны × 100%"></label><label class="full">Ескерту<textarea name="note">${esc(r?.note||'')}</textarea></label><div class="full"><button class="btn primary" type="submit">Сақтау</button></div>`;
 const preview=()=>{const total=+mf.elements.total.value,present=+mf.elements.present.value;document.getElementById('normPreview').value=total>0?(present/total*100).toFixed(1)+'%':'—'};mf.elements.total.oninput=preview;mf.elements.present.oninput=preview;preview();
 mf.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(mf));const total=Number(data.total),present=Number(data.present),absent=Number(data.absent);if(!Number.isInteger(total)||total<1||!Number.isInteger(present)||!Number.isInteger(absent)||present<0||absent<0||present+absent!==total){alert('«Бар» + «Жоқ» саны жалпы мұғалім санына тең болуы керек.');return}const item={id:rid||id(),document:data.document,total,present,absent,note:data.note||''};state.normDocuments=state.normDocuments||[];if(rid)state.normDocuments=state.normDocuments.map(x=>x.id===rid?item:x);else state.normDocuments.push(item);window.normActiveTab='docs';mb.classList.remove('show');save();toast('Құжат сақталды')};mb.classList.add('show')};
window.deleteNormDoc=rid=>{if(confirm('Жазбаны жою керек пе?')){state.normDocuments=state.normDocuments.filter(x=>x.id!==rid);window.normActiveTab='docs';save();toast('Жазба жойылды')}};
function normInfographic(){const rows=state.normDocuments||[];const docs=normTypes.map(name=>{const rs=rows.filter(x=>x.document===name);const total=rs.reduce((a,x)=>a+(+x.total||0),0),present=rs.reduce((a,x)=>a+(+x.present||0),0),absent=rs.reduce((a,x)=>a+(+x.absent||0),0);return {name,total,present,absent,percent:total?present/total*100:null}});const totals=docs.reduce((a,r)=>({total:a.total+r.total,present:a.present+r.present,absent:a.absent+r.absent}),{total:0,present:0,absent:0});const avg=totals.total?totals.present/totals.total*100:null;
 return `<div class="card" style="margin-top:20px"><div class="card-head"><div><h3>Нормативтік құжаттардың жүргізілуі</h3><p>Нақты енгізілген деректер негізіндегі инфографика</p></div></div><div class="dashboard-grid"><div class="kpi"><div class="label">Құжат бойынша жазбалар</div><div class="value">${rows.length}</div></div><div class="kpi"><div class="label">Бар (жиынтық)</div><div class="value">${totals.present}</div></div><div class="kpi"><div class="label">Жоқ (жиынтық)</div><div class="value">${totals.absent}</div></div><div class="kpi"><div class="label">Жалпы қамтылу</div><div class="value">${avg===null?'—':avg.toFixed(1)+'%'}</div></div></div>${docs.map(d=>`<div style="margin:18px 0"><div style="display:flex;justify-content:space-between;gap:10px"><strong>${esc(d.name)}</strong><strong>${d.percent===null?'Дерек жоқ':d.percent.toFixed(1)+'%'}</strong></div><div style="background:#e5e7eb;height:19px;border-radius:10px;overflow:hidden;margin:8px 0"><div style="background:#2563eb;height:100%;width:${d.percent??0}%;transition:width .3s"></div></div><div class="muted">Бар: ${d.present} · Жоқ: ${d.absent} · Жалпы: ${d.total}</div></div>`).join('')}<p class="muted">Бір құжат түрі бойынша бірнеше жазба енгізілсе, сандар жинақталып есептеледі. Жалпы қамтылу құжаттар бойынша өлшенеді.</p></div>`;
}


const qualityInternationalConfig={title:'Халықаралық зерттеу',desc:'Оқушылардың деңгейлері бойынша нәтижелер',fields:[{name:'className',label:'Сынып',required:true},{name:'teacher',label:'Пән мұғалімі',required:true},{name:'high',label:'Жоғары деңгей саны',type:'number',required:true},{name:'medium',label:'Орташа деңгей саны',type:'number',required:true},{name:'low',label:'Төмен деңгей саны',type:'number',required:true}],cols:[['className','Сынып'],['teacher','Пән мұғалімі'],['high','Жоғары'],['medium','Орташа'],['low','Төмен']]};
const progressConfigs={subjectQuality:{title:'Пәндер бойынша білім сапасы',fields:[{name:'quarter',label:'Тоқсан',type:'select',options:['I тоқсан','II тоқсан','III тоқсан','IV тоқсан'],required:true},{name:'teacher',label:'Мұғалім',required:true},{name:'subject',label:'Пән',type:'select',options:subjects,required:true},{name:'className',label:'Сынып',required:true},{name:'quality',label:'Білім сапасы (%)',type:'number',required:true},{name:'achievement',label:'Үлгерімі (%)',type:'number'}],cols:[['quarter','Тоқсан'],['teacher','Мұғалім'],['subject','Пән'],['className','Сынып'],['quality','Білім сапасы (%)'],['achievement','Үлгерімі (%)']]},lowClasses:{title:'Білім сапасы төмен көрсеткіш көрсеткен сыныптар',fields:[{name:'quarter',label:'Тоқсан',type:'select',options:['I тоқсан','II тоқсан','III тоқсан','IV тоқсан'],required:true},{name:'className',label:'Сынып',required:true},{name:'quality',label:'Білім сапасы (%)',type:'number',required:true},{name:'achievement',label:'Үлгерімі (%)',type:'number',required:true}],cols:[['quarter','Тоқсан'],['className','Сынып'],['quality','Білім сапасы (%)'],['achievement','Үлгерімі (%)']]}};
let progressTab='subjectQuality';
function renderProgressModule(){const root=document.getElementById('progress');if(!root)return;const cfg=progressConfigs[progressTab],rows=state[progressTab]||[];root.innerHTML=`<div class="card"><h3>Білімдегі олқылықтарды толықтыру және төмен көрсеткіштер бойынша жұмыстарды бақылау</h3><div class="tm-tabs"><button class="btn small ${progressTab==='subjectQuality'?'primary':'ghost'}" onclick="selectProgressTab('subjectQuality')">Пәндер бойынша білім сапасы</button><button class="btn small ${progressTab==='lowClasses'?'primary':'ghost'}" onclick="selectProgressTab('lowClasses')">Білім сапасы төмен сыныптар</button><button class="btn small ${progressTab==='old'?'primary':'ghost'}" onclick="selectProgressTab('old')">Бақылау жазбалары</button></div></div><div id="progressInner"></div>`;const el=document.getElementById('progressInner');if(progressTab==='old'){const old=state.progress||[];el.innerHTML=`<div class="card"><h3>Бақылау жазбалары (${old.length})</h3><button class="btn primary" onclick="openModal('progress')">+ Жазба қосу</button><div class="table-wrap"><table id="table-progress"><thead><tr><th>Тақырыбы</th><th>Тексеру мерзімі</th><th>Әрекет</th></tr></thead><tbody>${old.map(r=>`<tr><td>${esc(r.topic)}</td><td>${esc(r.checkDate)}</td><td><button class="btn small" onclick="openModal('progress','${r.id}')">Өңдеу</button> <button class="btn small danger" onclick="removeRow('progress','${r.id}')">Жою</button></td></tr>`).join('')}</tbody></table></div></div>`;return}el.innerHTML=`<div class="card"><div class="card-head"><h3>${cfg.title}</h3><button class="btn primary" onclick="openProgressRecord()">+ Жазба қосу</button></div><div class="toolbar"><input class="search" placeholder="Іздеу..." oninput="filterTable('${progressTab}',this.value)"></div><div class="table-wrap"><table id="table-${progressTab}"><thead><tr>${cfg.cols.map(c=>`<th>${c[1]}</th>`).join('')}<th>Әрекет</th></tr></thead><tbody>${rows.map(r=>`<tr data-search="${esc(JSON.stringify(r).toLowerCase())}">${cfg.cols.map(c=>`<td>${esc(r[c[0]]??'')}${['quality','achievement'].includes(c[0])?'%':''}</td>`).join('')}<td><button class="btn small" onclick="openProgressRecord('${r.id}')">Өңдеу</button> <button class="btn small danger" onclick="deleteProgressRecord('${r.id}')">Жою</button></td></tr>`).join('')||`<tr><td class="empty" colspan="${cfg.cols.length+1}">Әзірге жазба жоқ</td></tr>`}</tbody></table></div></div>`}
window.selectProgressTab=x=>{progressTab=x;renderProgressModule()};
window.openProgressRecord=rid=>{const type=progressTab,cfg=progressConfigs[type],r=(state[type]||[]).find(x=>x.id===rid)||{};document.getElementById('modalTitle').textContent=cfg.title;mf.innerHTML=cfg.fields.map(f=>field(f,r[f.name]??'')).join('')+'<div class="full"><button class="btn primary" type="submit">Сақтау</button></div>';for(const name of ['quality','achievement']){const el=mf.elements[name];if(el){el.min='0';el.max='100';el.step='0.1'}}mf.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(mf));for(const name of ['quality','achievement'])if(name in data){data[name]=Number(data[name]);if(!Number.isFinite(data[name])||data[name]<0||data[name]>100){alert('Пайыз 0–100 аралығында болуы керек');return}}state[type]=rid?state[type].map(x=>x.id===rid?{...x,...data}:x):[...state[type],{id:id(),...data}];mb.classList.remove('show');save();toast('Жазба сақталды')};mb.classList.add('show')};
window.deleteProgressRecord=rid=>{if(confirm('Жазбаны жою керек пе?')){state[progressTab]=state[progressTab].filter(x=>x.id!==rid);save()}};
const monitorTitles=['Нормативтік құжаттардың жүргізілуі','Оқу процесінің сапасын бақылау','Білімдегі олқылықтарды толықтыру және төмен көрсеткіштер бойынша жұмыстарды бақылау','Оқу-зерттеу қызметі','Мұғалімнің шеберлік және әдістемелік дайындық жағдайының деңгейін бақылау','Тәрбие процесінің, өткізілген іс-шаралардың сапасын бақылау','Мұғалімдер'];
let monitorTab=0;
function barStat(label,value,max=100,detail=''){const v=Number(value)||0;const w=max>0?Math.max(0,Math.min(100,v/max*100)):0;return `<div class="mon-bar"><div class="mon-line"><strong>${esc(label)}</strong><strong>${Number.isInteger(v)?v:v.toFixed(1)}${max===100?'%':''}</strong></div><div class="mon-track"><div class="mon-fill" style="width:${w}%"></div></div>${detail?`<div class="muted">${esc(detail)}</div>`:''}</div>`}
function metricCards(items){return `<div class="mon-metrics">${items.map(([name,value])=>`<div class="mon-metric"><div class="muted">${esc(name)}</div><strong>${esc(value)}</strong></div>`).join('')}</div>`}
function countBy(rows,key){const m={};rows.forEach(r=>{const k=String(r[key]||'Көрсетілмеген');m[k]=(m[k]||0)+1});return Object.entries(m).sort((a,b)=>b[1]-a[1])}
function monitorContent(tab){const norm=state.normDocuments||[],z=state.qualityZero||[],b=state.qualityBzb||[],bc=state.qualityBzbConclusion||[],intl=state.qualityInternational||[],sq=state.subjectQuality||[],lc=state.lowClasses||[],rs=state.researchSections||{},tm=state.teacherMaster||{},up=state.upbringingSections||{};const lines=(pairs)=>pairs.length?pairs.map(([k,v])=>barStat(k,v,Math.max(...pairs.map(x=>x[1]),1))).join(''):'<p class="muted">Әзірге дерек енгізілмеген.</p>';if(tab===0){const rows=['КТЖ','ЕБҚ мен құжат','Электронды журнал'];return metricCards([['Жазбалар',norm.length],['Құжат түрлері',new Set(norm.map(r=>r.document)).size]])+rows.map(name=>{const arr=norm.filter(r=>r.document===name),total=arr.reduce((a,r)=>a+(+r.total||0),0),present=arr.reduce((a,r)=>a+(+r.present||0),0),absent=arr.reduce((a,r)=>a+(+r.absent||0),0);return `<div class="mon-panel"><h4>${name}</h4>${total?barStat('Құжаттардың болуы',present/total*100,100,`Бар: ${present} · Жоқ: ${absent} · Жалпы: ${total}`):'<p class="muted">Дерек жоқ</p>'}${arr.filter(r=>r.note).map(r=>`<p class="mon-note"><b>Ескерту:</b> ${esc(r.note)}</p>`).join('')}</div>`}).join('')}
if(tab===1){const totals=z.map(r=>({n:+r.five+(+r.four)+(+r.three)+(+r.two),good:(+r.five)+(+r.four),passed:(+r.five)+(+r.four)+(+r.three)}));const n=totals.reduce((a,r)=>a+r.n,0),good=totals.reduce((a,r)=>a+r.good,0),passed=totals.reduce((a,r)=>a+r.passed,0);return metricCards([['«0» білім кесіндісі',z.length],['БЖБ/ТЖБ тексеруі',b.length],['Қорытынды',bc.length],['Халықаралық зерттеу',intl.length]])+`<div class="mon-panel"><h4>«0» білім кесіндісі</h4>${n?barStat('Білім сапасы',good/n*100)+barStat('Үлгерімі',passed/n*100):'<p class="muted">Дерек жоқ</p>'}${lines(countBy(z,'subject'))}</div><div class="mon-panel"><h4>БЖБ-ТЖБ талдауы (тоқсандар)</h4>${lines(countBy(b,'quarter'))}${lines(countBy(bc,'quarter'))}</div><div class="mon-panel"><h4>Халықаралық зерттеу — деңгейлер</h4>${lines([['Жоғары',intl.reduce((a,r)=>a+(+r.high||0),0)],['Орташа',intl.reduce((a,r)=>a+(+r.medium||0),0)],['Төмен',intl.reduce((a,r)=>a+(+r.low||0),0)]])}</div>`}
if(tab===2){const a=sq.map(r=>+r.quality).filter(Number.isFinite),c=lc.map(r=>+r.quality).filter(Number.isFinite),d=lc.map(r=>+r.achievement).filter(Number.isFinite);return metricCards([['Пәндер бойынша жазбалар',sq.length],['Төмен көрсеткішті сыныптар',lc.length]])+`<div class="mon-panel"><h4>Білім сапасы (орташа)</h4>${a.length?barStat('Пәндер бойынша',avg(a)):''}${c.length?barStat('Төмен көрсеткішті сыныптар',avg(c)):''}${d.length?barStat('Үлгерімі',avg(d)):''}</div><div class="mon-panel"><h4>Пәндер бойынша білім сапасы</h4>${sq.length?sq.map(r=>barStat(`${r.quarter} · ${r.subject} · ${r.className} · ${r.teacher}`,r.quality)).join(''):'<p class="muted">Дерек жоқ</p>'}</div><div class="mon-panel"><h4>Сыныптар бойынша</h4>${lc.map(r=>barStat(`${r.quarter} · ${r.className}`,r.quality,100,`Үлгерімі: ${r.achievement}%`)).join('')||'<p class="muted">Дерек жоқ</p>'}</div>`}
if(tab===3){const rows=rs[4]||[];return metricCards([['Ғылыми жобалар мен олимпиада жетістіктері',rows.length]])+`<div class="mon-panel"><h4>Деңгейі</h4>${lines(countBy(rows,'level'))}</div><div class="mon-panel"><h4>Орындар</h4>${lines(countBy(rows,'place'))}</div>`}
if(tab===4){const ach=tm['5_0']||[],spread=[0,1,2,3,4].flatMap(i=>tm['6_'+i]||[]),courses=tm['7_1']||[];return metricCards([['Жетістіктер',ach.length],['Тәжірибені тарату',spread.length],['Біліктілікті арттыру курстары',courses.length]])+`<div class="mon-panel"><h4>Жетістіктер деңгейі</h4>${lines(countBy(ach,'f2'))}</div><div class="mon-panel"><h4>Тәжірибені тарату деңгейі</h4>${lines(countBy(spread,'f2'))}</div><div class="mon-panel"><h4>Курс сағаттары</h4>${lines(countBy(courses,'f4'))}</div>`}
if(tab===5){const names=['Аудандық іс-шаралар','Мектепішілік іс-шаралар','Сыныптан тыс іс-шаралар','Аудандық есеп','Мектепішілік есеп'];const ids=[2,3,4,5,6];const items=ids.map((id,i)=>[names[i],(up[id]||[]).length]);return metricCards([['Барлық жазба',items.reduce((a,x)=>a+x[1],0)]])+`<div class="mon-panel"><h4>Іс-шаралар және есептер</h4>${lines(items)}</div><div class="mon-panel"><h4>Қамтылған оқушылар мен ата-аналар</h4>${lines([['Оқушылар',ids.slice(0,3).reduce((a,i)=>a+(up[i]||[]).reduce((b,r)=>b+(+r.children||0),0),0)],['Ата-аналар',ids.slice(0,3).reduce((a,i)=>a+(up[i]||[]).reduce((b,r)=>b+(+r.parents||0),0),0)]])}</div>`}
const teacherRows=[];function add(rows,key,kind){rows.forEach(r=>{const teacher=String(r[key]||'').trim();if(teacher)teacherRows.push({teacher,kind})})}add(z,'teacher','Білім кесіндісі');add(b,'teacher','БЖБ-ТЖБ');add(intl,'teacher','Халықаралық зерттеу');add(sq,'teacher','Пән сапасы');add(rs[2]||[],'teacher','Жұмыс жоспары');add(rs[3]||[],'teacher','Зерттеу');add(rs[4]||[],'teacher','Оқушы жетістігі');add(tm['5_0']||[],'f0','Жетістік');for(let i=0;i<5;i++)add(tm['6_'+i]||[],'f0','Тәжірибе тарату');add(tm['7_1']||[],'f0','Курс');add(up[4]||[],'teacher','Сыныптан тыс іс-шара');const names=[...new Set(teacherRows.map(r=>r.teacher))].sort((a,b)=>a.localeCompare(b,'kk'));const selected=window.monitorTeacher&&names.includes(window.monitorTeacher)?window.monitorTeacher:names[0];return metricCards([['Мұғалімдер саны',names.length],['Мұғалімге қатысты жазбалар',teacherRows.length]])+`<div class="mon-panel"><label>Мұғалімді таңдаңыз <select id="monitorTeacherSelect" onchange="window.monitorTeacher=this.value;renderDashboard()">${names.map(name=>`<option value="${esc(name)}" ${name===selected?'selected':''}>${esc(name)}</option>`).join('')}</select></label>${selected?`<h4>${esc(selected)}</h4>${lines(countBy(teacherRows.filter(r=>r.teacher===selected),'kind').map(x=>x))}`:'<p class="muted">Мұғалім туралы жазба жоқ</p>'}</div><p class="muted">Бір мұғалімнің аты-жөні барлық бөлімде бірдей жазылуы керек. Деректер жазбалар саны бойынша көрсетіледі.</p>`}
const monitorPalette=['#6366f1','#06b6d4','#10b981','#f59e0b','#f43f5e','#8b5cf6','#3b82f6','#ec4899'];
function monitorSvgBars(items,idx){
 const max=Math.max(1,...items.map(x=>x.value));const width=620, plot=480, left=116, row=43, height=Math.max(115,items.length*row+35);
 const bars=items.slice(0,12).map((it,i)=>{const y=17+i*row,w=Math.max(0,it.value/max*plot),color=monitorPalette[(i+idx)%monitorPalette.length];return `<g><title>${esc(it.name)}: ${it.value}</title><text x="${left-9}" y="${y+15}" text-anchor="end" class="mc-svg-label">${esc(it.name.length>19?it.name.slice(0,18)+'…':it.name)}</text><rect x="${left}" y="${y}" width="${plot}" height="22" rx="8" fill="#edf2f9"/><rect x="${left}" y="${y}" width="${w}" height="22" rx="8" fill="${color}"/><text x="${left+Math.min(w+8,plot-34)}" y="${y+16}" class="mc-svg-value">${it.value}</text></g>`}).join('');
 return `<svg class="mc-bars-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Көрсеткіштердің бағанды диаграммасы">${bars}</svg>`;
}
function monitorDonut(items,idx){
 const total=items.reduce((a,x)=>a+x.value,0);if(!total)return `<div class="mc-empty-visual">Диаграмма үшін дерек енгізіңіз</div>`;
 let cumulative=0;const circles=items.slice(0,8).map((it,i)=>{const share=it.value/total*100,off=-cumulative;cumulative+=share;return `<circle cx="86" cy="86" r="58" fill="none" stroke="${monitorPalette[(idx+i)%monitorPalette.length]}" stroke-width="25" stroke-dasharray="${share} ${100-share}" stroke-dashoffset="${off}" pathLength="100" transform="rotate(-90 86 86)"><title>${esc(it.name)}: ${it.value}</title></circle>`}).join('');
 return `<div class="mc-donut-layout"><svg viewBox="0 0 172 172" class="mc-donut" role="img" aria-label="Үлестік дөңгелек диаграмма"><circle cx="86" cy="86" r="58" fill="none" stroke="#edf2f9" stroke-width="25"/>${circles}<text x="86" y="80" text-anchor="middle" class="mc-donut-number">${total}</text><text x="86" y="101" text-anchor="middle" class="mc-donut-sub">барлығы</text></svg><div class="mc-legend">${items.slice(0,8).map((it,i)=>`<div class="mc-legend-row"><span class="mc-dot" style="background:${monitorPalette[(idx+i)%monitorPalette.length]}"></span><span>${esc(it.name)}</span><strong>${it.value}</strong></div>`).join('')}</div></div>`;
}
function enhanceMonitorCharts(root){
 root.querySelectorAll('.mon-panel').forEach((panel,index)=>{
  panel.classList.add('mc-panel');
  const bars=[...panel.querySelectorAll('.mon-bar')].map((el,i)=>{const name=el.querySelector('.mon-line strong')?.textContent?.trim()||`Көрсеткіш ${i+1}`;const valueText=el.querySelector('.mon-line strong:last-child')?.textContent||'0';const value=parseFloat(valueText.replace(',','.'))||0;return {name,value:Math.max(0,value)}});
  if(!bars.length)return;
  const chart=document.createElement('div');chart.className='mc-chart-area';
  chart.innerHTML=`<div class="mc-chart-head"><span>Көрнекі талдау</span><span class="mc-chart-caption">${bars.length} көрсеткіш</span></div>${monitorSvgBars(bars,index)}${monitorDonut(bars,index)}`;
  panel.insertBefore(chart,panel.firstElementChild?.nextSibling||null);
  panel.querySelectorAll('.mon-bar').forEach(el=>el.classList.add('mc-detail-bar'));
 });
 root.querySelectorAll('.mon-metric').forEach((el,i)=>{el.style.setProperty('--mc-accent',monitorPalette[i%monitorPalette.length]);});
}
renderDashboard=function(){const root=document.getElementById('dashboard');root.innerHTML=`<div class="card"><div class="card-head"><div><h3>Мониторинг</h3><p>Сайтқа енгізілген деректер негізіндегі автоматты талдау</p></div></div><div class="mon-tabs">${monitorTitles.map((name,i)=>`<button class="btn small ${i===monitorTab?'primary':'ghost'}" onclick="selectMonitorTab(${i})">${i+1}. ${esc(name)}</button>`).join('')}</div></div><div class="card"><h3>${esc(monitorTitles[monitorTab])}</h3>${monitorContent(monitorTab)}</div>`;enhanceMonitorCharts(root)};
window.selectMonitorTab=i=>{monitorTab=i;renderDashboard()};

