// Backups include the binary attachments (as data URLs) so they remain portable.
async function blobAsDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
async function traverseAttachments(obj,fn){if(!obj||typeof obj!=='object')return;for(const key of Object.keys(obj)){const value=obj[key];if(typeof value==='string'&&(value.startsWith('idb:')||value.startsWith('data:'))){obj[key]=await fn(value)}else if(value&&typeof value==='object')await traverseAttachments(value,fn)}}
async function backupState(){const copy=structuredClone(state);await traverseAttachments(copy,async ref=>ref.startsWith('idb:')?await blobAsDataUrl(await (await fetch(await fileUrl(ref))).blob()):ref);return copy}
async function restoreState(raw){const copy={...structuredClone(stateDefault),...raw};await traverseAttachments(copy,async ref=>{if(!ref.startsWith('data:'))return ref;const blob=await (await fetch(ref)).blob();return fileToDataURL(blob)});state=copy;save()}
document.getElementById('exportBtn').onclick=async()=>{try{toast('Резервтік көшірме дайындалып жатыр…');const backup=await backupState(),blob=new Blob([JSON.stringify(backup)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='mektepishilik_bakylau_tirkemelermen_backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Көшірме жүктелді')}catch(e){alert('Резервтік көшірме жасалмады: '+e.message)}};
document.getElementById('importInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{await restoreState(JSON.parse(await f.text()));toast('Деректер және тіркемелер импортталды')}catch(err){alert('JSON импорты орындалмады: '+err.message)}};
document.getElementById('resetBtn').onclick=()=>{if(confirm('Барлық енгізілген деректі тазарту керек пе?')){state=structuredClone(stateDefault);save();toast('Деректер тазартылды')}};
renderAll();

