document.getElementById('schoolPhotoInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/'))return alert('Сурет файлын таңдаңыз');state.schoolPhoto=await fileToDataURL(f);save();renderSchoolPhoto()};

