// Monitoring V5: data-driven sections, record-level charts and teacher-specific views.
const monColors=['#2563eb','#14b8a6','#f59e0b','#8b5cf6','#f43f5e','#0ea5e9'];
const monNum=v=>Math.max(0,Number(v)||0);
const monList=(rows,key)=>{const out={};rows.forEach(r=>{const name=String(r[key]||'Белгісіз');out[name]=(out[name]||0)+1});return Object.entries(out).map(([label,value])=>({label,value}))};
function monChart(title,values,subtitle='',mode='donut'){
 const data=values.map(x=>({label:String(x.label),value:monNum(x.value)}));const sum=data.reduce((s,x)=>s+x.value,0);let offset=0;
 const segments=data.map((x,i)=>{const percent=sum?x.value/sum*100:0;const out=`<circle cx="80" cy="80" r="57" fill="none" stroke="${monColors[i%monColors.length]}" stroke-width="22" pathLength="100" stroke-dasharray="${percent} ${100-percent}" stroke-dashoffset="${-offset}" transform="rotate(-90 80 80)"><title>${esc(x.label)}: ${x.value}</title></circle>`;offset+=percent;return out}).join('');
 const bars=data.map((x,i)=>`<div class="m5-bar"><div class="m5-bar-label"><span>${esc(x.label)}</span><strong>${x.value.toLocaleString('kk-KZ')}</strong></div><div class="m5-track"><div style="width:${sum?x.value/Math.max(...data.map(y=>y.value),1)*100:0}%;background:${monColors[i%monColors.length]}"></div></div></div>`).join('');
 return `<article class="m5-card"><h4>${esc(title)}</h4>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}${!sum?'<p class="m5-empty">Әзірге дерек енгізілмеген</p>':mode==='bars'?bars:`<div class="m5-chart"><svg viewBox="0 0 160 160" role="img" aria-label="${esc(title)}"><circle cx="80" cy="80" r="57" fill="none" stroke="#e5eaf3" stroke-width="22"/>${segments}<text x="80" y="78" text-anchor="middle" font-size="25" font-weight="800" fill="#172554">${sum}</text><text x="80" y="97" text-anchor="middle" font-size="10" fill="#64748b">барлығы</text></svg><div class="m5-legend">${data.map((x,i)=>`<div><i style="background:${monColors[i%monColors.length]}"></i><span>${esc(x.label)}</span><b>${x.value}</b></div>`).join('')}</div></div>`}</article>`;
}
const monGroup=(title,content)=>`<section class="m5-group"><h3>${esc(title)}</h3><div class="m5-grid">${content||'<p class="muted">Әзірге дерек жоқ</p>'}</div></section>`;
const monPercent=(label,value)=>monChart(label,[{label:'Білім сапасы',value:monNum(value)},{label:'Қалған бөлігі',value:Math.max(0,100-monNum(value))}],'Пайыз (%)');
function monTeacherRows(){const rs=state.researchSections||{},tm=state.teacherMaster||{},up=state.upbringingSections||{};const groups=[['«0» білім кесіндісі',state.qualityZero||[],'teacher'],['БЖБ/ТЖБ',state.qualityBzb||[],'teacher'],['Халықаралық зерттеу',state.qualityInternational||[],'teacher'],['Пәндер бойынша білім сапасы',state.subjectQuality||[],'teacher'],['Ғылыми жоба жетістіктері',rs[4]||[],'teacher'],['Жас мұғалім–тәлімгер',tm['2_0']||[],'f0'],['Кәсіби даму',tm['4_0']||[],'f0'],['Жетістіктер',tm['5_0']||[],'f0'],['Тәжірибе тарату',[0,1,2,3,4].flatMap(i=>tm['6_'+i]||[]),'f0'],['Біліктілікті арттыру',tm['7_1']||[],'f0']];return groups}
function monitoringV5(tab){
 const norm=state.normDocuments||[],z=state.qualityZero||[],b=state.qualityBzb||[],intl=state.qualityInternational||[],sq=state.subjectQuality||[],lc=state.lowClasses||[],rs=state.researchSections||{},tm=state.teacherMaster||{},up=state.upbringingSections||{};
 const levels=['аудан','облыс','республика','халықаралық'];
 const normName=n=>n==='ЕБҚ мен құжат'?'ЕБҚ мен ҮО құжаты':n;
 const lvl=n=>{n=String(n||'').toLowerCase();return n.includes('халық')?'халықаралық':n.includes('респуб')?'республика':n.includes('облыс')?'облыс':n.includes('аудан')?'аудан':'басқа'};
 const byLevel=(rows,key)=>levels.map(x=>({label:x,value:rows.filter(r=>lvl(r[key])===x).length}));
 const per=(name,value)=>monPercent(name,Math.min(100,monNum(value)));
 const info=(r,fields)=>`<div class="m6-details">${fields.map(([k,label])=>r[k]!==undefined&&r[k]!==''?`<div><b>${esc(label)}:</b> ${esc(String(r[k]))}</div>`:'').join('')}</div>`;
 const docStatus=teacher=>['КТЖ','ЕБҚ мен ҮО құжаты','Электронды журнал'].map(doc=>{const arr=norm.filter(r=>normName(r.document)===doc),flag=arr.some(r=>String(r.note||'').toLocaleLowerCase('kk').includes(teacher.toLocaleLowerCase('kk')));return `<div class="m6-status"><span>${esc(doc)}</span><strong class="${flag?'m6-bad':'m6-good'}">${flag?'Толық емес':'Толық'}</strong></div>`}).join('');
 if(tab===0)return monGroup('Нормативтік құжаттардың жүргізілуі',['КТЖ','ЕБҚ мен ҮО құжаты','Электронды журнал'].map(doc=>{const arr=norm.filter(r=>normName(r.document)===doc);return monChart(doc,[{label:'Бар',value:arr.reduce((n,r)=>n+monNum(r.present),0)},{label:'Жоқ',value:arr.reduce((n,r)=>n+monNum(r.absent),0)}])+`<div class="m5-notes"><b>Ескерту — ${esc(doc)}</b>${arr.filter(r=>r.note).map(r=>`<p>${esc(r.note)}</p>`).join('')||'<p>Ескерту жоқ</p>'}</div>`}).join(''));
 if(tab===1)return monGroup('А) «0» білім кесіндісі — әр жазбаға бір диаграмма',z.map(r=>monChart(`${r.subject||'Пән'} · ${r.teacher||'Мұғалім'}`,[{label:'5',value:r.five},{label:'4',value:r.four},{label:'3',value:r.three},{label:'2',value:r.two}],`Білім сапасы: ${r.quality||0}% · Үлгерімі: ${r.achievement||0}%`)).join(''))+monGroup('Ә) Халықаралық зерттеу — нақты оқушы саны',intl.map(r=>monChart(`${r.className||r.grade||'Сынып'} · ${r.teacher||'Мұғалім'}`,[{label:'Жоғары',value:r.high},{label:'Орташа',value:r.medium},{label:'Төмен',value:r.low}])).join(''));
 if(tab===2)return monGroup('А) Пәндер бойынша білім сапасы — әр жазбаға екі диаграмма',sq.map(r=>per(`${r.quarter||''} · ${r.subject||''} · ${r.className||''} · ${r.teacher||''} — Білім сапасы`,r.quality)+per(`${r.quarter||''} · ${r.subject||''} · ${r.className||''} · ${r.teacher||''} — Үлгерімі`,r.achievement)).join(''))+monGroup('Ә) Білім сапасы төмен сыныптар — әр жазба',lc.map(r=>monChart(`${r.quarter||''} · ${r.className||'Сынып'}`,[{label:'Білім сапасы (%)',value:r.quality},{label:'Үлгерімі (%)',value:r.achievement}],'Пайыз','bars')).join(''));
 if(tab===3)return monGroup('Ғылыми жобалар мен олимпиада жетістіктері — деңгейлер',levels.map(l=>monChart(l.toUpperCase(),[{label:'Жетістіктер',value:(rs[4]||[]).filter(r=>lvl(r.level)===l).length}],'Жазбалар саны','bars')).join(''));
 if(tab===4){const ach=tm['5_0']||[],spread=[0,1,2,3,4].flatMap(i=>tm['6_'+i]||[]),courses=tm['7_1']||[];return monGroup('А) Жетістіктер — деңгейлер',levels.map(l=>monChart(l,[{label:'Жетістіктер',value:ach.filter(r=>lvl(r.f2)===l).length}],'','bars')).join(''))+monGroup('Ә) Тәжірибені жинақтау және тарату — деңгейлер',levels.map(l=>monChart(l,[{label:'Материалдар',value:spread.filter(r=>lvl(r.f2)===l).length}],'','bars')).join(''))+monGroup('Б) Біліктілікті арттыру',monChart('Курстар — мұғалімдер бойынша',monList(courses,'f0'),'Курстарда деңгей өрісі жоқ, сондықтан мұғалімдер бойынша көрсетілді','bars'))}
 if(tab===5){const summary=[...new Set(upbringingGroups.map(g=>g.group))].map(group=>({label:group.replace(/^\d+\. /,''),value:upbringingGroups.filter(g=>g.group===group).reduce((n,g)=>n+(up[g.storeKey]||[]).length,0)}));return monGroup('Тәрбие процесі — 13 бағыт бойынша жазбалар',monChart('Бөлімдер бойынша тіркелген жазбалар',summary,'Жазбалар саны','bars'))+monGroup('Бөлімдер және тіркелген құжаттар',summary.map(r=>`<article class="m5-card"><b>${esc(r.label)}</b><p>Жазба саны: ${r.value}</p></article>`).join(''));}
 const groups=monTeacherRows(),names=[...new Set(groups.flatMap(([title,rows,key])=>rows.map(r=>String(r[key]||'').trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'kk'));const selected=names.includes(window.monitorTeacher)?window.monitorTeacher:names[0];
 const filtered=label=>{const g=groups.find(x=>x[0]===label);return g?g[1].filter(r=>String(r[g[2]]||'').trim()===selected):[]};
 const detailChart=(label,rows,fields,valuesFn)=>rows.map((r,i)=>monChart(`${label} #${i+1}`,valuesFn(r),`${selected}`,'bars')+`<article class="m5-card">${info(r,fields)}</article>`).join('')||'<p class="muted">Дерек жоқ</p>';
 const counts=label=>monChart(label,[{label:'Жазбалар',value:filtered(label).length}],'','bars');
 const tmLessons=(key)=> (tm[key]||[]).filter(r=>String(r.f0||'').trim()===selected);
 return `<div class="m5-select"><label>Мұғалімді таңдаңыз <select onchange="window.monitorTeacher=this.value;renderDashboard()">${names.map(n=>`<option value="${esc(n)}" ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}</select></label></div>`+(selected?
 monGroup('А) Нормативтік құжаттардың жүргізілуі',`<article class="m5-card">${docStatus(selected)}<p class="muted">Мәртебе ескерту мәтініндегі аты-жөнге байланысты анықталады.</p></article>`)+
 monGroup('Ә) Оқу процесінің сапасы',
 detailChart('«0» білім кесіндісі',filtered('«0» білім кесіндісі'),[['subject','Пән'],['quality','Білім сапасы (%)'],['achievement','Үлгерімі (%)'] ],r=>[{label:'5',value:r.five},{label:'4',value:r.four},{label:'3',value:r.three},{label:'2',value:r.two}])+
 detailChart('БЖБ/ТЖБ',filtered('БЖБ/ТЖБ'),[['purpose','Мақсаты'],['quarter','Тоқсан'],['className','Сынып'],['checkDate','Тексеру мерзімі'],['journalMatch','Журнал сәйкестігі'],['omjMatch','ОМЖ сәйкестігі'],['criteriaMatch','Критерий сәйкестігі'],['recommendation','Ұсыныс']],r=>[{label:'Жазба',value:1}])+
 detailChart('Халықаралық зерттеу',filtered('Халықаралық зерттеу'),[['className','Сынып']],r=>[{label:'Жоғары',value:r.high},{label:'Орташа',value:r.medium},{label:'Төмен',value:r.low}]))+
 monGroup('Б) Білімдегі олқылықтарды толықтыру',detailChart('Пәндер бойынша білім сапасы',filtered('Пәндер бойынша білім сапасы'),[['quarter','Тоқсан'],['subject','Пән'],['className','Сынып']],r=>[{label:'Білім сапасы (%)',value:r.quality},{label:'Үлгерімі (%)',value:r.achievement}]))+
 monGroup('В) Оқу-зерттеу қызметі',detailChart('Ғылыми жоба жетістіктері',filtered('Ғылыми жоба жетістіктері'),[['student','Оқушы'],['grade','Сынып'],['level','Деңгей'],['place','Орын']],r=>[{label:r.level||'Жетістік',value:1}]))+
 monGroup('Г) Мұғалімнің шеберлігі',
 detailChart('Жас мұғалім–тәлімгер',tmLessons('2_0'),tmLesson.map((x,i)=>['f'+i,x]),r=>[{label:'Сабаққа қатысу',value:1}])+
 detailChart('Кәсіби даму',tmLessons('4_0'),tmLesson.map((x,i)=>['f'+i,x]),r=>[{label:'Сабаққа қатысу',value:1}])+
 monGroup('Жетістіктер — конкурс, деңгей және нәтиже',filtered('Жетістіктер').map((r,i)=>monChart(`${r.f1||'Конкурс'} · ${r.f2||'Деңгей көрсетілмеген'}`,[{label:r.f3||'Нәтиже көрсетілмеген',value:1}],`Конкурс: ${r.f1||'—'} · Деңгей: ${r.f2||'—'} · Нәтиже: ${r.f3||'—'}`,'bars')).join(''))+
 monGroup('Тәжірибені жинақтау және тарату — 5 бөлім',tmGroups[6].children.map((child,i)=>{
  const rows=(tm['6_'+i]||[]).filter(r=>String(r.f0||'').trim()===selected);
  return monChart(child[0],[...new Set(rows.map(r=>r.f2).filter(Boolean))].map(level=>({label:level,value:rows.filter(r=>r.f2===level).length})),`Жазбалар: ${rows.length}`,'bars')+
  (rows.length?`<article class="m5-card">${rows.map(r=>info(r,child[1].filter(x=>x!=='Дәлелдеме').map((label,k)=>['f'+k,label]))).join('')}</article>`:'');
 }).join(''))+
 monGroup('Біліктілікті арттыру курстары — тақырып, орын, мерзім',
  filtered('Біліктілікті арттыру').map((r,i)=>monChart(`${r.f1||'Курс'} · ${r.f2||'Өткізілген орын көрсетілмеген'}`,[{label:'Сағат саны',value:monNum(r.f4)}],`Тақырыбы: ${r.f1||'—'} · Курсты өткен орны: ${r.f2||'—'} · Мерзімі: ${r.f3||'—'}`,'bars')+`<article class="m5-card">${info(r,[['f0','Пән мұғалімі'],['f1','Тақырыбы'],['f2','Курсты өткен орны'],['f3','Мерзімі'],['f4','Сағат саны']])}</article>`).join('')||'<p class="muted">Курс жазбалары жоқ</p>'))+
 monGroup('Д) Тәрбие процесі',counts('Сыныптан тыс іс-шаралар')):'<p class="muted">Мұғалім туралы жазбалар жоқ</p>');
}
renderDashboard=function(){const root=document.getElementById('dashboard');root.innerHTML=`<div class="card"><h3>Мониторинг</h3><p class="muted">Нақты енгізілген деректер бойынша 7 бағыттағы көрнекі талдау</p><div class="m5-tabs">${monitorTitles.map((x,i)=>`<button class="btn small ${monitorTab===i?'primary':'ghost'}" onclick="selectMonitorTab(${i})">${i+1}. ${esc(x)}</button>`).join('')}</div></div>${monitoringV5(monitorTab)}`};

async function migrateLegacyFiles(){try{const before=JSON.stringify(state);if(!before.includes('data:'))return;const copy=structuredClone(state);await traverseAttachments(copy,async ref=>{if(!ref.startsWith('data:'))return ref;const blob=await (await fetch(ref)).blob();return fileToDataURL(blob)});localStorage.setItem(KEY,JSON.stringify(copy));state=copy;renderAll();toast('Бұрынғы PDF/JPG файлдары жаңа қоймаға көшірілді')}catch(e){console.warn('Legacy migration:',e)}}
migrateLegacyFiles();
